test("Core historical-reuse live-pin repair records its exact change", async () => {
	const record = await readCoreHistoricalEvidenceReuseLivePinRepair();
	assert.equal(record.schemaVersion, 1);
	assert.equal(record.milestone
		, "core-historical-evidence-reuse-live-pin-repair-source-v1");
	assert.equal(record.predecessorCommit
		, coreHistoricalEvidenceReuseLivePinRepairPredecessor);
	assert.equal(record.implementationCommit
		, coreHistoricalEvidenceReuseLivePinRepairImplementation);
	assert.deepEqual(record.updates.map(update => update.path)
		, coreHistoricalEvidenceReuseLivePinRepairImplementationPaths);
	assert.deepEqual(record.integrationUpdates.map(update => update.path)
		, coreHistoricalEvidenceReuseLivePinRepairIntegrationPaths);
	assert.deepEqual(record.historyAdditions.map(addition => addition.path)
		, coreHistoricalEvidenceReuseLivePinRepairHistoryAdditions);
	assert.equal(git(["rev-parse"
		, `${coreHistoricalEvidenceReuseLivePinRepairImplementation}^`]).trim()
		, coreHistoricalEvidenceReuseLivePinRepairPredecessor);
	assert.deepEqual(git(["diff", "--name-only"
		, coreHistoricalEvidenceReuseLivePinRepairPredecessor
		, coreHistoricalEvidenceReuseLivePinRepairImplementation])
		.trim().split("\n").sort()
		, [...coreHistoricalEvidenceReuseLivePinRepairImplementationPaths].sort());
});

test("Core historical-reuse live pins cite the exact current sources", async () => {
	const document = JSON.parse(await readFile("docs/type-surface.v1.json", "utf8"));
	const expected = new Map([
		["tests/callback-subtype-hosted-evidence.test.mjs", 8]
		, ["tests/helpers/callback-subtype-hosted-evidence-sources.mjs", 8]
		, ["tests/helpers/php-wasm-direct-fin-promotion-tests.mjs", 4]
		, ["tests/helpers/php-wasm-subtype-promotion-tests.mjs", 2]
	]);
	const citations = new Map([...expected].map(([path]) => [path, []]));
	for(const evidence of document.evidence)
		for(const file of evidence.files)
			if(citations.has(file.path)) citations.get(file.path).push(file.sha256);
	for(const [path, count] of expected)
	{
		assert.equal(citations.get(path).length, count, path);
		assert.deepEqual([...new Set(citations.get(path))]
			, [sha256(await readFile(path))], path);
	}
});

test("Core historical-reuse live-pin repair reverses every transition", async () => {
	const record = await readCoreHistoricalEvidenceReuseLivePinRepair();
	for(const update of [...record.updates, ...record.integrationUpdates])
	{
		const current = await sourceAtFinHistoryMilestone(
			update.path, update.currentSha256
			, beforeCoreHistoricalEvidenceReuseLivePinRepairSource);
		const base = record.integrationUpdates.includes(update)
			? coreHistoricalEvidenceReuseLivePinRepairImplementation
			: coreHistoricalEvidenceReuseLivePinRepairPredecessor;
		const previous = git(["show", `${base}:${update.path}`]);
		assert.equal(reverseCoreHistoricalEvidenceReuseLivePinRepairUpdate(
			current, update), previous, update.path);
		assert.equal(beforeFinRefinementSource(
			update.path, current, update.previousSha256), previous, update.path);
		assert.ok(finRefinementNormalizationPaths.includes(update.path));
	}
});

test("Core historical-reuse live-pin repair rejects altered transitions", async () => {
	const update = (await readCoreHistoricalEvidenceReuseLivePinRepair()).updates[0];
	const current = await sourceAtFinHistoryMilestone(
		update.path, update.currentSha256
		, beforeCoreHistoricalEvidenceReuseLivePinRepairSource);
	for(const forged of [{ ...update, currentSha256: "0".repeat(64) }
		, { ...update, previousSha256: "0".repeat(64) }
		, { ...update, path: "unrelated.mjs" }
		, { ...update, edits: [] }
		, { ...update, edits: [...update.edits, update.edits[0]] }])
		assert.throws(() => reverseCoreHistoricalEvidenceReuseLivePinRepairUpdate(
			current, forged));
	assert.equal(beforeCoreHistoricalEvidenceReuseLivePinRepairSource(
		update.path, current + "unknown"), current + "unknown");
});

test("Core historical-reuse live-pin writer rejects another checkout", async t => {
	const root = await mkdtemp(join(
		tmpdir(), "lean-core-historical-reuse-live-pin-guard-"
	));
	t.after(() => rm(root, { recursive: true }));
	const result = spawnSync(process.execPath, [resolve(
		"scripts/update-core-historical-evidence-reuse-live-pin-repair-source-history.mjs"
	)], { cwd: root, encoding: "utf8", timeout: 15_000 });
	assert.notEqual(result.status, 0);
	assert.equal(result.stdout, "");
	assert.deepEqual(await readdir(root), []);
});

